def currency_symbol(currency):
    return CURRENCY_SYMBOLS.get(str(currency or "USD").upper(), "$")


def format_currency(amount, currency="USD", show_sign=False):
    """Format a stored amount for display without converting its value."""
    if amount in (None, ""):
        return "Unavailable"
    try:
        number = Decimal(str(amount))
    except (InvalidOperation, TypeError, ValueError):
        return "Unavailable"
    if not number.is_finite():
        return "Unavailable"
    code = str(currency or "USD").upper()
    decimals = 0 if code == "JPY" else 2
    formatted = f"{abs(number):,.{decimals}f}"
    symbol = currency_symbol(code)
    if show_sign:
        sign = "-" if number < 0 else "+" if number > 0 else ""
        return f"{sign}{symbol}{formatted}"
    return f"{'-' if number < 0 else ''}{symbol}{formatted}"


def translate(text, language="en"):
    language = str(language or "en").lower()
    return TRANSLATIONS.get(language, TRANSLATIONS["en"]).get(text, text)
